insert into public.recipes (slug, name, description, meal_types, servings, prep_minutes, difficulty, equipment, instructions, cooked_yield_g, reliability, source_name, source_url, is_demo) values ('owsianka-bananowa', 'Owsianka bananowa z masłem orzechowym', 'Szybkie śniadanie na mleku z bananem.', array['breakfast']::text[], 1, 10, 'easy', array['stove']::text[], array['Zagotuj mleko w małym garnku.', 'Wsyp płatki i gotuj na małym ogniu 3–4 minuty, mieszając.', 'Przełóż do miski, dodaj banana i masło orzechowe.']::text[], 400, 'unverified', 'Przepis przykładowy (demo) — nieprzetestowany, masa po przygotowaniu szacunkowa', null, true);
